import json
import re
from lfx.custom.custom_component.component import Component
from lfx.io import MessageTextInput, StrInput, Output
from lfx.schema.message import Message

HIGH_ALERT_DRUGS = {"warfarin", "enoxaparin", "clexane", "lovenox", "heparin", "insulin", "digoxin", "phenytoin", "levetiracetam", "methadone", "morphine", "fentanyl"}

class PMRHighAlertHardStopGate(Component):
    display_name = "02. PMR High-Alert Hard Stop & Action Validator"
    description = "Memeriksa apakah kasus memiliki obat ISMP High-Alert dan memastikan konfirmasi eksplisit serta alasan wajib (untuk EDIT/REJECT/ESCALATE) sebelum diteruskan ke Audit Trail."
    icon = "octagon-alert"
    name = "PMRHighAlertHardStopGate"

    inputs = [
        MessageTextInput(name="review_message", display_name="Pesan Keputusan Apoteker / Agen", required=True),
        StrInput(name="case_id", display_name="Default Case / Encounter ID", value="P001"),
        StrInput(name="pharmacist_id", display_name="Default Pharmacist ID", value="PHARM-001"),
        StrInput(name="actor_type", display_name="Actor Type (human / agent_via_mcp)", value="human"),
        StrInput(name="high_alert_present", display_name="Daftar Obat High-Alert pada Kasus", value="warfarin, enoxaparin")
    ]
    outputs = [
        Output(display_name="Validated HITL Gate Payload", name="gate_payload", method="evaluate_gate")
    ]

    def evaluate_gate(self) -> Message:
        text = (getattr(self.review_message, "text", None) or str(self.review_message or "")).strip()
        actor_type = (self.actor_type or "human").strip().lower()

        # Parse action (APPROVE / EDIT / REJECT / ESCALATE / DRAFT_REVIEW)
        actions_map = {
            "DRAFT_REVIEW": re.compile(r"\b(draft[_\s-]*review|draft)\b", re.IGNORECASE),
            "ESCALATE": re.compile(r"\b(escalat(?:e|ed)|eskalasi)\b", re.IGNORECASE),
            "APPROVE": re.compile(r"\b(approve[d]?|setuju|disetujui|setujui)\b", re.IGNORECASE),
            "REJECT": re.compile(r"\b(reject(?:ed)?|tolak|ditolak)\b", re.IGNORECASE),
            "EDIT": re.compile(r"\b(edit(?:ed)?|revisi)\b", re.IGNORECASE),
        }
        matched = [act for act, pat in actions_map.items() if pat.search(text)]

        # ADR-07: If invoked by an AI agent via MCP, force action to DRAFT_REVIEW (never autonomous final APPROVE)
        if actor_type != "human":
            action = "DRAFT_REVIEW"
        elif len(matched) == 1:
            action = matched[0]
        elif not matched:
            return Message(text=json.dumps({
                "gate_passed": False,
                "error_code": "INVALID_OR_MISSING_ACTION",
                "message": "Aksi tidak ditemukan. Gunakan tepat satu aksi: APPROVE, EDIT, REJECT, ESCALATE, atau DRAFT_REVIEW."
            }, ensure_ascii=False))
        else:
            return Message(text=json.dumps({
                "gate_passed": False,
                "error_code": "AMBIGUOUS_ACTION",
                "message": f"Aksi ambigu ({matched}). Gunakan hanya satu aksi keputusan per pengiriman."
            }, ensure_ascii=False))

        # Check High-Alert Hard Stop for APPROVE
        ha_list = [d.strip().lower() for d in (self.high_alert_present or "").split(",") if d.strip()]
        if action == "APPROVE" and ha_list:
            ack_ok = any(k in text.lower() for k in ("ack", "konfirmasi", "terverifikasi", "verified", "high-alert", "warfarin"))
            if not ack_ok:
                return Message(text=json.dumps({
                    "gate_passed": False,
                    "error_code": "HIGH_ALERT_NOT_ACKNOWLEDGED",
                    "missing_acknowledgement": ha_list,
                    "message": f"HARD STOP: Kasus memiliki obat High-Alert ({ha_list}). Sertakan kata 'terverifikasi' atau konfirmasi obat High-Alert sebelum APPROVE."
                }, ensure_ascii=False))

        # Mandatory clinical note check for EDIT / REJECT / ESCALATE
        if action in ("EDIT", "REJECT", "ESCALATE") and len(text.split()) < 3:
            return Message(text=json.dumps({
                "gate_passed": False,
                "error_code": "MANDATORY_REASON_MISSING",
                "message": f"Aksi {action} mewajibkan alasan/catatan klinis yang memadai."
            }, ensure_ascii=False))

        case_match = re.search(r"\b(P\d+|ENC-[A-Za-z0-9_-]+|CASE-\d+)\b", text, re.IGNORECASE)
        cid = case_match.group(1).upper() if case_match else (self.case_id or "P001")

        out = {
            "gate_passed": True,
            "case_id": cid,
            "pharmacist_id": self.pharmacist_id or "PHARM-001",
            "actor_type": actor_type,
            "action": action,
            "high_alert_acknowledged": ha_list if action == "APPROVE" else [],
            "pharmacist_note": text
        }
        self.status = f"Gate PASSED ({action})"
        return Message(text=json.dumps(out, ensure_ascii=False))
